//! The denoise models Ember knows about: what each one is, who may use it, and where to fetch it.
//!
//! None is part of Ember. A model with an address here can be downloaded when the user asks and has accepted
//! its terms; anything else is brought by the user as an `.onnx` file with a `denoise-model.json` beside it.

#[cfg(any(feature = "rawnind-model", test))]
use crate::licence::{Commercial, Licence};

use crate::manifest::DenoiserManifest;
#[cfg(any(feature = "rawnind-model", test))]
use crate::manifest::{Domain, Gain};

/// A known model, and how to get it.
pub struct Known {
    pub manifest: DenoiserManifest,
    /// What to fetch (an archive or the `.onnx` itself); `None` when the user must bring the file.
    pub download: Option<Download>,
    /// The `.onnx` inside the downloaded archive (`None`: the download is the `.onnx`).
    pub entry: Option<&'static str>,
}

/// RawNIND's UtNet2 for Bayer sensors, as published for darktable (`rawdenoise-nind.dtmodel`, a zip with a Bayer and a
/// linear model). Its weights are GPL-3.0; the training pictures are CC BY 4.0 and CC0.
#[cfg(any(feature = "rawnind-model", test))]
fn rawnind_bayer() -> Known {
    let manifest = DenoiserManifest {
        id: "rawnind-bayer".into(),
        name: "RawNIND UtNet2 (Bayer)".into(),
        version: "1.0".into(),
        licence: Licence {
            name: "GPL-3.0".into(),
            commercial: Commercial::Yes,
            url: Some("https://www.gnu.org/licenses/gpl-3.0.html".into()),
            notice: "The weights are published under the GNU General Public License v3. Ember does not include them: they \
                     are downloaded to your computer at your request and used by it only. If you pass the model file on, the \
                     GPL applies to that copy. Commercial use is subject to the GPL terms, including applicable source, licence and notice obligations on redistribution."
                .into(),
        },
        source: Some("https://github.com/darktable-org/darktable-ai/tree/master/models/rawdenoise-nind".into()),
        sha256: Some("da27509dab6a2915da67e988acd86cf71f9d5bbc8d1aa0ed32933578a887b901".into()),
        size_bytes: Some(31_056_425),
        provenance: "Trained on RawNIND, real photographs of the same scenes taken noisy and clean (images CC BY 4.0 and CC0, \
                     published on Wikimedia Commons and by the University of Louvain). Paper: arXiv 2501.08924."
            .into(),
        domain: Domain::BayerToRgb,
        tile: 512,
        overlap: 64,
        gain: Gain::MatchMean { nominal: 1.0e6, max_deviation: 0.05 },
    };
    let download = Download {
        id: manifest.id.clone(),
        url: "https://github.com/darktable-org/darktable-ai/releases/download/release-5.6.0/rawdenoise-nind.dtmodel".into(),
        file_name: "rawdenoise-nind.dtmodel".into(),
        size_bytes: 57_700_134,
        sha256: "d71b5f1e727c85a359e6f74dca9e2016c9d8fc3e2f7ac3e9b347d80ceca969af".into(),
    };
    Known { manifest, download: Some(download), entry: Some("model_bayer.onnx") }
}

/// Every model Ember knows.
pub fn all() -> Vec<Known> {
    #[cfg(feature = "rawnind-model")]
    {
        vec![rawnind_bayer()]
    }
    #[cfg(not(feature = "rawnind-model"))]
    {
        Vec::new()
    }
}

/// The known model with this id.
pub fn find(id: &str) -> Option<Known> {
    all().into_iter().find(|k| k.manifest.id == id)
}

/// The known model whose `.onnx` has this SHA-256.
pub fn by_sha256(sha256: &str) -> Option<DenoiserManifest> {
    all().into_iter().map(|k| k.manifest).find(|m| m.sha256.as_deref() == Some(sha256))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::manifest::validate;

    #[test]
    fn known_models_are_valid_unique_and_downloaded_over_https() {
        let all = all();
        assert_eq!(all.is_empty(), !cfg!(feature = "rawnind-model"));
        validate(&rawnind_bayer().manifest).unwrap();
        for (i, k) in all.iter().enumerate() {
            validate(&k.manifest).unwrap();
            assert!(all.iter().skip(i + 1).all(|o| o.manifest.id != k.manifest.id), "unique ids");
            assert!(!k.manifest.licence.name.is_empty() && !k.manifest.licence.notice.is_empty(), "terms are shown before use");
            if let Some(d) = &k.download {
                assert_eq!(d.id, k.manifest.id);
                assert!(d.url.starts_with("https://") && d.sha256.len() == 64 && d.size_bytes > 0);
                // a name that cannot leave the staging folder
                assert!(!d.file_name.contains(['/', '\\']) && !d.file_name.starts_with('.'));
            }
            // a model that may not be used commercially is never offered for download
            if k.manifest.licence.commercial == Commercial::No {
                assert!(k.download.is_none(), "{}", k.manifest.id);
            }
        }
        assert_eq!(find("rawnind-bayer").is_some(), cfg!(feature = "rawnind-model"));
        assert!(find("nothing").is_none());
        assert_eq!(
            by_sha256("da27509dab6a2915da67e988acd86cf71f9d5bbc8d1aa0ed32933578a887b901").map(|m| m.id),
            if cfg!(feature = "rawnind-model") { Some("rawnind-bayer".into()) } else { None }
        );
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Download {
    pub id: String,
    pub url: String,
    /// The name the file is kept under while it waits for the user to accept its terms.
    pub file_name: String,
    pub size_bytes: u64,
    pub sha256: String,
}

pub fn host(url: &str) -> &str {
    url.strip_prefix("https://").and_then(|r| r.split('/').next()).unwrap_or("")
}

//! A denoise model's manifest: what the model takes and gives, how big its tiles are and who may use it, as
//! plain data.
//!
//! It comes from a `denoise-model.json` next to the `.onnx` file or from the user's `catalog.json`. Both are
//! untrusted: [`validate`] must pass before a manifest is used, and [`parse`] applies it after reading JSON of
//! bounded size. The licence, id and address rules are the face models' (`crate::licence`).

use crate::licence::{Licence, valid_id};
use serde::{Deserialize, Serialize};

/// Largest `denoise-model.json` we read.
pub const MAX_MANIFEST_BYTES: usize = 64 * 1024;
/// Largest model file we accept (bytes).
pub const MAX_MODEL_BYTES: u64 = 2 * 1024 * 1024 * 1024;

/// What the model takes and what it gives.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Domain {
    /// The sensor's Bayer mosaic (black subtracted, white at 1, not white balanced) packed as four planes
    /// `[R, G1, G2, B]` of its 2 × 2 cells, forced to RGGB; gives camera RGB at the mosaic's resolution, so
    /// the picture is denoised and demosaiced in one step and must not be demosaiced again.
    BayerToRgb,
}

/// How the model's output scale is brought back to the input's.
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "camelCase")]
pub enum Gain {
    /// The output already has the input's scale.
    None,
    /// The output has a scale of its own, `nominal` times the input's (a million, for one model) and a little
    /// different from tile to tile: each tile is scaled so that its channel means equal the input's. A tile too
    /// dark to measure, or whose measured scale is further than `maxDeviation` (a fraction, 0.05 = 5 %) from
    /// `nominal`, is scaled as if it were within that limit.
    MatchMean { nominal: f32, max_deviation: f32 },
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct DenoiserManifest {
    /// Lowercase letters, digits, `.` `_` `-`.
    pub id: String,
    pub name: String,
    pub version: String,
    #[serde(default)]
    pub licence: Licence,
    /// Where the weights come from (an `https://` page or file), for the user's information.
    #[serde(default)]
    pub source: Option<String>,
    /// Lowercase hex SHA-256 of the `.onnx` file, when known.
    #[serde(default)]
    pub sha256: Option<String>,
    #[serde(default)]
    pub size_bytes: Option<u64>,
    /// What the model was trained on, in plain words; says "undisclosed" when it is.
    #[serde(default)]
    pub provenance: String,
    pub domain: Domain,
    /// Side of the square the model runs on, in packed cells (the file's fixed input size).
    pub tile: u32,
    /// Cells neighbouring tiles share; the picture is blended across them.
    pub overlap: u32,
    pub gain: Gain,
}

#[derive(Debug, PartialEq, thiserror::Error)]
pub enum ManifestError {
    #[error("`{0}` is not valid: {1}")]
    Field(&'static str, String),
    #[error("not a denoise-model manifest: {0}")]
    Parse(String),
    #[error("a manifest may be at most {MAX_MANIFEST_BYTES} bytes")]
    TooLarge,
}

fn bad<T>(field: &'static str, why: impl Into<String>) -> Result<T, ManifestError> {
    Err(ManifestError::Field(field, why.into()))
}

fn text(field: &'static str, s: &str, min: usize, max: usize) -> Result<(), ManifestError> {
    let n = s.chars().count();
    if n < min || n > max {
        return bad(field, format!("must be {min} to {max} characters"));
    }
    if s.chars().any(|c| c.is_control() && c != '\n') {
        return bad(field, "must not contain control characters");
    }
    Ok(())
}

fn url(field: &'static str, u: &Option<String>) -> Result<(), ManifestError> {
    match u {
        None => Ok(()),
        Some(u) if u.len() <= 500 && u.starts_with("https://") && !u.chars().any(|c| c.is_control() || c.is_whitespace()) => Ok(()),
        Some(_) => bad(field, "must be an https:// address of at most 500 characters"),
    }
}

/// Check a manifest from outside before trusting it.
pub fn validate(m: &DenoiserManifest) -> Result<(), ManifestError> {
    if !valid_id(&m.id) {
        return bad("id", "1 to 64 lowercase letters, digits, `.`, `_` or `-`, starting with a letter or digit");
    }
    text("name", &m.name, 1, 80)?;
    text("version", &m.version, 1, 40)?;
    text("provenance", &m.provenance, 0, 1000)?;
    text("licence.name", &m.licence.name, 0, 80)?;
    text("licence.notice", &m.licence.notice, 0, 2000)?;
    url("licence.url", &m.licence.url)?;
    url("source", &m.source)?;
    if let Some(h) = &m.sha256
        && !(h.len() == 64 && h.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b)))
    {
        return bad("sha256", "must be 64 lowercase hex digits");
    }
    if let Some(n) = m.size_bytes
        && (n == 0 || n > MAX_MODEL_BYTES)
    {
        return bad("sizeBytes", format!("must be between 1 and {MAX_MODEL_BYTES}"));
    }
    // a U-Net with four poolings wants a multiple of 16; nothing smaller than 64 or larger than 2048 is a tile
    if !(64..=2048).contains(&m.tile) || !m.tile.is_multiple_of(16) {
        return bad("tile", "must be a multiple of 16 from 64 to 2048");
    }
    // tiles must overlap by less than half, or one tile's blend ramps would run into its other neighbour's
    if !m.overlap.is_multiple_of(2) || m.overlap < 16 || m.overlap.saturating_mul(2) >= m.tile {
        return bad("overlap", "must be even, at least 16 and less than half the tile");
    }
    if let Gain::MatchMean { nominal, max_deviation } = m.gain {
        if !(nominal.is_finite() && (1e-6..=1e12).contains(&nominal)) {
            return bad("gain.nominal", "must be between 0.000001 and 1000000000000");
        }
        if !(max_deviation.is_finite() && (0.0..=0.5).contains(&max_deviation)) {
            return bad("gain.maxDeviation", "must be between 0 and 0.5");
        }
    }
    Ok(())
}

/// Read and validate a `denoise-model.json`.
pub fn parse(bytes: &[u8]) -> Result<DenoiserManifest, ManifestError> {
    if bytes.len() > MAX_MANIFEST_BYTES {
        return Err(ManifestError::TooLarge);
    }
    let bytes = bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes);
    let m: DenoiserManifest = serde_json::from_slice(bytes).map_err(|e| ManifestError::Parse(e.to_string()))?;
    validate(&m)?;
    Ok(m)
}

#[cfg(test)]
mod tests {
    use super::*;

    pub(crate) fn sample() -> DenoiserManifest {
        DenoiserManifest {
            id: "nind-bayer".into(),
            name: "Bayer denoiser".into(),
            version: "1".into(),
            licence: Licence::default(),
            source: Some("https://example.org/model.onnx".into()),
            sha256: None,
            size_bytes: Some(31_000_000),
            provenance: "trained on real raw noise pairs".into(),
            domain: Domain::BayerToRgb,
            tile: 512,
            overlap: 64,
            gain: Gain::MatchMean { nominal: 1.0e6, max_deviation: 0.05 },
        }
    }

    #[test]
    fn a_good_manifest_round_trips() {
        let m = sample();
        let json = serde_json::to_vec(&m).unwrap();
        assert_eq!(parse(&json).unwrap(), m);
    }

    #[test]
    fn bad_fields_are_named() {
        let cases: Vec<(&str, Box<dyn Fn(&mut DenoiserManifest)>)> = vec![
            ("id", Box::new(|m| m.id = "../evil".into())),
            ("id", Box::new(|m| m.id = String::new())),
            ("name", Box::new(|m| m.name = "x\u{7}".into())),
            ("source", Box::new(|m| m.source = Some("http://insecure".into()))),
            ("sha256", Box::new(|m| m.sha256 = Some("XYZ".into()))),
            ("sizeBytes", Box::new(|m| m.size_bytes = Some(0))),
            ("tile", Box::new(|m| m.tile = 500)),
            ("tile", Box::new(|m| m.tile = 4096)),
            ("overlap", Box::new(|m| m.overlap = 300)),
            ("overlap", Box::new(|m| m.overlap = 63)),
            ("gain.maxDeviation", Box::new(|m| m.gain = Gain::MatchMean { nominal: 1.0, max_deviation: f32::NAN })),
            ("gain.maxDeviation", Box::new(|m| m.gain = Gain::MatchMean { nominal: 1.0, max_deviation: 2.0 })),
            ("gain.nominal", Box::new(|m| m.gain = Gain::MatchMean { nominal: 0.0, max_deviation: 0.1 })),
            ("gain.nominal", Box::new(|m| m.gain = Gain::MatchMean { nominal: f32::INFINITY, max_deviation: 0.1 })),
        ];
        for (field, edit) in cases {
            let mut m = sample();
            edit(&mut m);
            match validate(&m) {
                Err(ManifestError::Field(f, _)) => assert_eq!(f, field),
                other => panic!("{field}: {other:?}"),
            }
        }
    }

    #[test]
    fn parse_is_bounded_and_tolerant() {
        assert_eq!(parse(&vec![b' '; MAX_MANIFEST_BYTES + 1]), Err(ManifestError::TooLarge));
        assert!(matches!(parse(b"{ nope"), Err(ManifestError::Parse(_))));
        assert!(matches!(parse(b""), Err(ManifestError::Parse(_))));
        let mut with_bom = vec![0xEF, 0xBB, 0xBF];
        with_bom.extend(serde_json::to_vec(&sample()).unwrap());
        assert!(parse(&with_bom).is_ok());
    }
}

//! Bounded, borrowed decoding of the ONNX fields used by denoise, from the public Apache-2.0 schema:
//! https://github.com/onnx/onnx/blob/main/onnx/onnx.proto3
//! No generated code, protoc, recursive graph decoding, or external tensor files.

use crate::net::{MAX_OPS, MAX_WEIGHTS, NetError};

const MAX_ITEMS: usize = MAX_OPS * 4;
const MAX_STRING: usize = 4096;
pub(super) const MAX_BYTES: usize = MAX_WEIGHTS * 4 + 16 * 1024 * 1024;

type Result<T> = std::result::Result<T, NetError>;
fn bad() -> NetError {
    NetError::Invalid("malformed or oversized ONNX protobuf".into())
}

struct Fields<'a> {
    rest: &'a [u8],
    count: usize,
}
enum Wire<'a> {
    Int(u64),
    Bytes(&'a [u8]),
    F32(f32),
    Other,
}

fn varint(rest: &mut &[u8]) -> Result<u64> {
    let mut value = 0u64;
    for shift in (0..70).step_by(7) {
        let (b, tail) = rest.split_first().ok_or_else(bad)?;
        *rest = tail;
        if shift == 63 && *b > 1 {
            return Err(bad());
        }
        value |= u64::from(*b & 127) << shift;
        if b & 128 == 0 {
            return Ok(value);
        }
    }
    Err(bad())
}

impl<'a> Fields<'a> {
    fn new(rest: &'a [u8]) -> Self {
        Self { rest, count: 0 }
    }
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        let out = self.rest.get(..n).ok_or_else(bad)?;
        self.rest = self.rest.get(n..).ok_or_else(bad)?;
        Ok(out)
    }
    fn next(&mut self) -> Result<Option<(u32, Wire<'a>)>> {
        if self.rest.is_empty() {
            return Ok(None);
        }
        self.count += 1;
        if self.count > MAX_WEIGHTS {
            return Err(bad());
        }
        let tag = varint(&mut self.rest)?;
        let number = u32::try_from(tag >> 3).map_err(|_| bad())?;
        if number == 0 || number >= 1 << 29 {
            return Err(bad());
        }
        let wire = match tag & 7 {
            0 => Wire::Int(varint(&mut self.rest)?),
            1 => {
                self.take(8)?;
                Wire::Other
            }
            2 => {
                let n = usize::try_from(varint(&mut self.rest)?).map_err(|_| bad())?;
                Wire::Bytes(self.take(n)?)
            }
            5 => {
                let b: [u8; 4] = self.take(4)?.try_into().map_err(|_| bad())?;
                Wire::F32(f32::from_le_bytes(b))
            }
            _ => return Err(bad()),
        };
        Ok(Some((number, wire)))
    }
}

fn string(b: &[u8]) -> Result<String> {
    if b.len() > MAX_STRING {
        return Err(bad());
    }
    std::str::from_utf8(b).map(str::to_owned).map_err(|_| bad())
}
fn push<T>(v: &mut Vec<T>, value: T, cap: usize) -> Result<()> {
    if v.len() >= cap {
        return Err(bad());
    }
    v.try_reserve(1).map_err(|_| bad())?;
    v.push(value);
    Ok(())
}
fn ints(w: Wire<'_>, out: &mut Vec<i64>, cap: usize) -> Result<()> {
    match w {
        Wire::Int(v) => push(out, v as i64, cap),
        Wire::Bytes(mut b) => {
            while !b.is_empty() {
                let v = varint(&mut b)?;
                push(out, v as i64, cap)?;
            }
            Ok(())
        }
        _ => Err(bad()),
    }
}

#[derive(Default)]
pub(super) struct AttributeProto {
    pub name: String,
    /// `None` when the file has no float value for the attribute.
    pub f: Option<f32>,
    /// The declared attribute type (1 float, 2 int, 3 string, 7 ints); 0 when the file does not say.
    pub kind: i64,
    pub i: i64,
    pub s: Vec<u8>,
    pub ints: Vec<i64>,
}
#[derive(Default)]
pub(super) struct NodeProto {
    pub input: Vec<String>,
    pub output: Vec<String>,
    pub op_type: String,
    pub attribute: Vec<AttributeProto>,
}
#[derive(Default)]
pub(super) struct TensorProto<'a> {
    pub name: String,
    pub dims: Vec<i64>,
    pub data_type: i32,
    pub raw_data: &'a [u8],
    pub float_data: Vec<f32>,
}
pub(super) struct ValueInfoProto {
    pub name: String,
    pub channels: Option<usize>,
}
#[derive(Default)]
pub(super) struct Graph<'a> {
    pub node: Vec<NodeProto>,
    pub initializer: Vec<TensorProto<'a>>,
    pub input: Vec<ValueInfoProto>,
    pub output: Vec<ValueInfoProto>,
}

fn attribute(b: &[u8]) -> Result<AttributeProto> {
    let mut a = AttributeProto::default();
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        match (n, w) {
            (1, Wire::Bytes(b)) => a.name = string(b)?,
            (2, Wire::F32(v)) if a.f.is_none() => a.f = Some(v),
            (3, Wire::Int(v)) => a.i = v as i64,
            (4, Wire::Bytes(b)) => {
                if b.len() > MAX_STRING {
                    return Err(bad());
                }
                a.s = b.to_vec();
            }
            (8, w) => ints(w, &mut a.ints, 16)?,
            (20, Wire::Int(v @ (1 | 2 | 3 | 7))) if a.kind == 0 => a.kind = v as i64,
            _ => return Err(NetError::Unsupported("unknown attribute value".into())),
        }
    }
    Ok(a)
}
fn node(b: &[u8]) -> Result<NodeProto> {
    let mut a = NodeProto::default();
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        match (n, w) {
            (1, Wire::Bytes(b)) => push(&mut a.input, string(b)?, 4)?,
            (2, Wire::Bytes(b)) => push(&mut a.output, string(b)?, 2)?,
            (4, Wire::Bytes(b)) => a.op_type = string(b)?,
            (5, Wire::Bytes(b)) => push(&mut a.attribute, attribute(b)?, 16)?,
            (7, Wire::Bytes(b)) if !b.is_empty() => return Err(NetError::Unsupported("a custom operator domain".into())),
            _ => {}
        }
    }
    Ok(a)
}
fn tensor(b: &[u8]) -> Result<TensorProto<'_>> {
    let mut a = TensorProto::default();
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        match (n, w) {
            (1, w) => ints(w, &mut a.dims, 8)?,
            (2, Wire::Int(v)) => a.data_type = i32::try_from(v).map_err(|_| bad())?,
            (4, Wire::F32(v)) => push(&mut a.float_data, v, MAX_WEIGHTS)?,
            (4, Wire::Bytes(b)) => {
                if !b.len().is_multiple_of(4) {
                    return Err(bad());
                }
                for chunk in b.as_chunks::<4>().0 {
                    push(&mut a.float_data, f32::from_le_bytes(*chunk), MAX_WEIGHTS)?;
                }
            }
            (8, Wire::Bytes(b)) => a.name = string(b)?,
            (9, Wire::Bytes(b)) => {
                if b.len() > MAX_WEIGHTS * 4 {
                    return Err(bad());
                }
                a.raw_data = b;
            }
            (13, _) | (14, Wire::Int(1..)) => return Err(NetError::Unsupported("external tensor data".into())),
            _ => {}
        }
    }
    Ok(a)
}
fn channel_shape(b: &[u8]) -> Result<Option<usize>> {
    let mut fields = Fields::new(b);
    let mut dim = 0;
    let mut channels = None;
    while let Some((n, w)) = fields.next()? {
        if let (1, Wire::Bytes(b)) = (n, w) {
            if dim >= 8 {
                return Err(bad());
            }
            let mut df = Fields::new(b);
            while let Some((n, w)) = df.next()? {
                if let (1, Wire::Int(v)) = (n, w)
                    && dim == 1
                {
                    channels = usize::try_from(v).ok().filter(|&v| v > 0);
                }
            }
            dim += 1;
        }
    }
    Ok(channels)
}
fn channel_type(b: &[u8]) -> Result<Option<usize>> {
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        if let (1, Wire::Bytes(b)) = (n, w) {
            let mut tf = Fields::new(b);
            let (mut elem, mut channels) = (0, None);
            while let Some((n, w)) = tf.next()? {
                match (n, w) {
                    (1, Wire::Int(v)) => elem = v,
                    (2, Wire::Bytes(b)) => channels = channel_shape(b)?,
                    _ => {}
                }
            }
            return Ok(if elem == 1 { channels } else { None });
        }
    }
    Ok(None)
}
fn value_info(b: &[u8]) -> Result<ValueInfoProto> {
    let mut out = ValueInfoProto { name: String::new(), channels: None };
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        match (n, w) {
            (1, Wire::Bytes(b)) => out.name = string(b)?,
            (2, Wire::Bytes(b)) => out.channels = channel_type(b)?,
            _ => {}
        }
    }
    Ok(out)
}
fn graph(b: &[u8]) -> Result<Graph<'_>> {
    let mut out = Graph::default();
    let mut fields = Fields::new(b);
    while let Some((n, w)) = fields.next()? {
        match (n, w) {
            (1, Wire::Bytes(b)) => push(&mut out.node, node(b)?, MAX_ITEMS)?,
            (5, Wire::Bytes(b)) => push(&mut out.initializer, tensor(b)?, MAX_ITEMS)?,
            (11, Wire::Bytes(b)) => push(&mut out.input, value_info(b)?, MAX_ITEMS)?,
            (12, Wire::Bytes(b)) => push(&mut out.output, value_info(b)?, 1)?,
            (15, _) => return Err(NetError::Unsupported("sparse initializers".into())),
            _ => {}
        }
    }
    Ok(out)
}
pub(super) fn decode(b: &[u8]) -> Result<Graph<'_>> {
    if b.len() > MAX_BYTES {
        return Err(bad());
    }
    let mut fields = Fields::new(b);
    let mut out = None;
    while let Some((n, w)) = fields.next()? {
        if let (7, Wire::Bytes(b)) = (n, w) {
            if out.is_some() {
                return Err(bad());
            }
            out = Some(graph(b)?);
        }
    }
    out.ok_or_else(bad)
}
